(() => {
  const PETS = {
    rabbit:{label:'兔子',image:'data:image/png;base64,',defaultName:'雪球',favorite:'carrot',stages:[
      {level:1,name:'白雪幼兔',title:'幼年期',deco:''},
      {level:3,name:'蓬鬆雪兔',title:'成長期',deco:'🌸'},
      {level:5,name:'花冠靈兔',title:'成熟期',deco:'🌼'},
      {level:8,name:'月光神兔',title:'最終進化',deco:'👑'}]},
    dog:{label:'狗狗',image:'data:image/png;base64,',defaultName:'奶油',favorite:'bone',stages:[
      {level:1,name:'奶油幼犬',title:'幼年期',deco:''},
      {level:3,name:'活力小犬',title:'成長期',deco:'🐾'},
      {level:5,name:'紅巾守護犬',title:'成熟期',deco:'🎀'},
      {level:8,name:'星耀神犬',title:'最終進化',deco:'👑'}]},
    cat:{label:'貓咪',image:'data:image/png;base64,',defaultName:'奶茶',favorite:'fish',stages:[
      {level:1,name:'奶茶幼貓',title:'幼年期',deco:''},
      {level:3,name:'蓬鬆小貓',title:'成長期',deco:'🐾'},
      {level:5,name:'蝴蝶結靈貓',title:'成熟期',deco:'🎀'},
      {level:8,name:'星夜神貓',title:'最終進化',deco:'👑'}]},
    snake:{label:'小蛇',image:'data:image/png;base64,',defaultName:'心心',favorite:'egg',stages:[
      {level:1,name:'心心幼蛇',title:'幼年期',deco:''},
      {level:3,name:'森林精靈蛇',title:'成長期',deco:'🌿'},
      {level:5,name:'翡翠靈蛇',title:'成熟期',deco:'💎'},
      {level:8,name:'夢幻神蛇',title:'最終進化',deco:'👑'}]},
    dino:{label:'恐龍',image:'data:image/png;base64,',defaultName:'芽芽',favorite:'leaf',stages:[
      {level:1,name:'萌萌幼龍',title:'幼年期',deco:''},
      {level:3,name:'活力芽芽龍',title:'成長期',deco:'🌱'},
      {level:5,name:'森林守護龍',title:'成熟期',deco:'🌿'},
      {level:8,name:'彩虹龍王',title:'最終進化',deco:'👑'}]}
  };

  const FOODS = {
    carrot:{name:'胡蘿蔔',emoji:'🥕',price:20},
    bone:{name:'骨頭餅乾',emoji:'🦴',price:25},
    fish:{name:'小魚乾',emoji:'🐟',price:25},
    egg:{name:'營養蛋',emoji:'🥚',price:30},
    leaf:{name:'嫩葉套餐',emoji:'🌿',price:20}
  };

  const LEVEL_THRESHOLDS=[0,5,12,20,30,42,56,72];
  const TYPE_LABELS={
    g1_add20:'20以內加法',g1_sub20:'20以內減法',g1_add100:'100以內加法',g1_compare:'數字比大小',
    g2_addsub:'二位數加減',g2_mul:'九九乘法',g2_div:'基礎除法',g2_time:'時間換算',
    g3_addsub:'三位數加減',g3_mul:'三位數乘一位數',g3_div:'三位數除一位數',g3_fraction:'分數初步',
    g4_addsub:'四位數加減',g4_mul:'多位數乘法',g4_div:'多位數除法',g4_factor:'因數判斷',g4_decimal:'小數運算',
    g5_fraction:'分數運算',g5_decimal:'小數運算',g5_average:'平均數',g5_volume:'體積',
    g6_ratio:'比與比例',g6_percent:'百分率',g6_speed:'速率',g6_circle:'圓周長與面積',
    g7_exp:'指數',g7_sci:'科學記號',g7_linear:'一元一次方程式',g7_system:'二元一次聯立方程式',
    g7_proportion:'比例式',g7_factor:'因數與倍數',
    g8_quadratic:'一元二次方程式',g8_sqrt:'平方根',g8_pythagorean:'畢氏定理',
    g8_formula:'乘法公式',g8_poly:'多項式',g8_arithmetic:'等差數列與級數',
    g8_geometric:'等比數列',g8_triangle:'三角形內角與外角'
  };

  const defaultState={
    pet:'rabbit',grade:1,coins:50,correct:0,combo:0,ability:100,soundOn:true,
    lastHungerUpdate:Date.now(),
    answer:0,currentType:'g1_add20',questionStartedAt:Date.now(),
    recent:[],inventory:{carrot:0,bone:0,fish:0,egg:0,leaf:0},
    typeStats:{},
    daily:{date:'',answered:0,correct:0,feeds:0,maxCombo:0,gachaUsed:false},
    pets:{
      rabbit:{name:'雪球',hunger:50,correct:0,stagePenalty:0,starved:false},
      dog:{name:'奶油',hunger:50,correct:0,stagePenalty:0,starved:false},
      cat:{name:'奶茶',hunger:50,correct:0,stagePenalty:0,starved:false},
      snake:{name:'心心',hunger:50,correct:0,stagePenalty:0,starved:false},
      dino:{name:'芽芽',hunger:50,correct:0,stagePenalty:0,starved:false}
    }
  };

  let state=loadState();
  let audioContext=null;
  const $=id=>document.getElementById(id);

  function clone(obj){return JSON.parse(JSON.stringify(obj))}
  function todayKey(){return new Date().toISOString().slice(0,10)}
  function loadState(){
    return window.SaveSystem.load(defaultState,todayKey())
  }
  function saveState(){
    window.SaveSystem.save(state)
  }
  function rand(min,max){return Math.floor(Math.random()*(max-min+1))+min}
  function getLevel(petKey=state.pet){
    let level=1;
    const petCorrect=(state.pets[petKey]&&state.pets[petKey].correct)||0;
    LEVEL_THRESHOLDS.forEach((t,i)=>{if(petCorrect>=t)level=i+1});
    return Math.min(level,8)
  }
  function getStageIndex(level){return level>=8?3:level>=5?2:level>=3?1:0}
  function getEffectiveStageIndex(petKey=state.pet){
    const ps=state.pets[petKey];
    return Math.max(0,getStageIndex(getLevel(petKey))-(ps.stagePenalty||0))
  }
  function getExpression(hunger){
    if(hunger>=90)return{face:'😋',text:'滿足',cls:'satisfied'};
    if(hunger>=50)return{face:'😊',text:'開心',cls:'happy'};
    return{face:'😢',text:'憂鬱',cls:'gloomy'}
  }
  function ensureTypeStats(type){
    if(!state.typeStats[type])state.typeStats[type]={correct:0,total:0,time:0}
    return state.typeStats[type]
  }
  function recentAccuracy(){
    if(!state.recent.length)return 0;
    return state.recent.filter(x=>x.correct).length/state.recent.length
  }
  function averageTime(){
    if(!state.recent.length)return 0;
    return state.recent.reduce((s,x)=>s+x.time,0)/state.recent.length
  }
  function typeAccuracy(type){
    const s=state.typeStats[type];
    return !s||!s.total?null:s.correct/s.total
  }
  function strongestAndWeakest(){
    const rows=Object.entries(state.typeStats).filter(([,s])=>s.total>=2);
    if(!rows.length)return{strong:'尚無資料',weak:'尚無資料'};
    rows.sort((a,b)=>(b[1].correct/b[1].total)-(a[1].correct/a[1].total));
    return{strong:TYPE_LABELS[rows[0][0]],weak:TYPE_LABELS[rows[rows.length-1][0]]}
  }
  function showNotice(text){
    const el=$('notice');el.textContent=text;el.classList.add('show');
    clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>el.classList.remove('show'),1800)
  }
  function ensureAudio(){
    if(!audioContext){
      const AC=window.AudioContext||window.webkitAudioContext;
      if(AC)audioContext=new AC()
    }
    if(audioContext&&audioContext.state==='suspended')audioContext.resume()
  }
  function tone(freq,d=.12,type='sine',vol=.05,delay=0){
    if(!state.soundOn)return;
    ensureAudio();if(!audioContext)return;
    const start=audioContext.currentTime+delay,osc=audioContext.createOscillator(),gain=audioContext.createGain();
    osc.type=type;osc.frequency.value=freq;
    gain.gain.setValueAtTime(.0001,start);
    gain.gain.exponentialRampToValueAtTime(vol,start+.015);
    gain.gain.exponentialRampToValueAtTime(.0001,start+d);
    osc.connect(gain).connect(audioContext.destination);osc.start(start);osc.stop(start+d+.02)
  }
  function sound(kind){
    if(kind==='correct'){tone(660,.1);tone(880,.13,'sine',.05,.1);tone(1047,.16,'sine',.04,.2)}
    if(kind==='wrong'){tone(330,.16,'triangle',.04);tone(247,.2,'triangle',.035,.12)}
    if(kind==='feed'){tone(523,.08);tone(659,.1,'sine',.04,.08);tone(784,.12,'sine',.035,.16)}
    if(kind==='buy'){tone(880,.08,'square',.03);tone(1175,.1,'square',.025,.08)}
    if(kind==='level'){[523,659,784,1047].forEach((f,i)=>tone(f,.2,'sine',.045,i*.1))}
  }
  function reactPet(){
    const img=$('petImage');img.classList.remove('react');void img.offsetWidth;img.classList.add('react')
  }
  function applyHungerDecay(){
    const now=Date.now();
    const elapsedHours=Math.floor((now-state.lastHungerUpdate)/3600000);
    if(elapsedHours<=0)return false;
    const loss=elapsedHours*2;
    Object.keys(state.pets).forEach(key=>{
      const ps=state.pets[key];
      ps.hunger=Math.max(0,ps.hunger-loss);
      if(ps.hunger===0&&!ps.starved){
        ps.starved=true;
        ps.stagePenalty=getStageIndex(getLevel(key))>0?1:0;
      }
    });
    state.lastHungerUpdate+=elapsedHours*3600000;
    saveState();
    return true
  }
  function interactPet(action='pet'){
    const ps=state.pets[state.pet],name=ps.name;
    const messages={
      pet:[`${name}舒服地瞇起眼睛。`,`你輕輕摸摸${name}，牠開心地靠近你。`,`摸摸成功！${name}看起來很安心。`],
      play:[`${name}興奮地和你玩了一會兒！`,`${name}追著玩具跑來跑去。`,`玩耍時間讓${name}充滿活力！`],
      hug:[`你抱抱${name}，牠露出幸福的表情。`,`${name}安靜地依偎著你。`,`抱抱成功！${name}感受到你的關心。`]
    };
    const list=messages[action]||messages.pet;
    $('interactionMessage').textContent=list[rand(0,list.length-1)];
    reactPet();sound('feed')
  }
  function flyCoins(amount){
    const el=document.createElement('div');el.className='coin-fly';el.textContent=`🪙 +${amount}`;
    el.style.left='45%';el.style.top='55%';document.body.appendChild(el);setTimeout(()=>el.remove(),950)
  }
  function taskDefinitions(){return[
    {key:'answered',label:'完成 15 題',target:15,reward:30},
    {key:'correct',label:'答對 10 題',target:10,reward:40},
    {key:'feeds',label:'餵食 3 次',target:3,reward:25}
  ]}
  function claimedKey(key){return `claimed_${key}`}
  function claimTask(task){
    if(state.daily[claimedKey(task.key)]||state.daily[task.key]<task.target)return;
    state.daily[claimedKey(task.key)]=true;state.coins+=task.reward;flyCoins(task.reward);sound('correct');
    showNotice(`任務完成，獲得 ${task.reward} 金幣`);saveState();render()
  }
  function renderDailyTasks(){
    const wrap=$('dailyTasks');wrap.innerHTML='';
    taskDefinitions().forEach(task=>{
      const value=Math.min(state.daily[task.key],task.target),done=value>=task.target,claimed=!!state.daily[claimedKey(task.key)];
      const card=document.createElement('div');card.className='task-card'+(done?' done':'');
      card.innerHTML=`<h3>${done?'✅':'🎯'} ${task.label}</h3><div>${value} / ${task.target}</div><div class="task-progress"><div style="width:${value/task.target*100}%"></div></div><p>獎勵：${task.reward} 金幣</p>`;
      const b=document.createElement('button');b.className=done&&!claimed?'primary':'secondary';b.textContent=claimed?'已領取':done?'領取獎勵':'進行中';b.disabled=!done||claimed;
      b.addEventListener('click',()=>claimTask(task));card.appendChild(b);wrap.appendChild(card)
    })
  }
  function renderTeacherSummary(){
    const accuracy=state.daily.answered?Math.round(state.daily.correct/state.daily.answered*100):0;
    const avg=averageTime();
    const data=[['今日答題',state.daily.answered+' 題'],['今日正確率',accuracy+'%'],['最高連擊',state.daily.maxCombo+' 題'],['平均速度',state.recent.length?avg.toFixed(1)+' 秒':'尚無資料']];
    $('teacherSummary').innerHTML=data.map(([a,b])=>`<div class="teacher-card"><span>${a}</span><b>${b}</b></div>`).join('')
  }
  function useGacha(){
    if(state.daily.gachaUsed)return;
    const prizes=[
      {text:'獲得 50 金幣',coins:50},{text:'獲得 30 金幣',coins:30},
      {text:'獲得胡蘿蔔 ×2',food:'carrot',count:2},{text:'獲得小魚乾 ×2',food:'fish',count:2},
      {text:'獲得營養蛋 ×1',food:'egg',count:1},{text:'獲得嫩葉套餐 ×2',food:'leaf',count:2}
    ];
    const prize=prizes[rand(0,prizes.length-1)];
    if(prize.coins){state.coins+=prize.coins;flyCoins(prize.coins)}
    if(prize.food)state.inventory[prize.food]+=prize.count;
    state.daily.gachaUsed=true;sound('level');showNotice(prize.text);saveState();render()
  }
  function renderGacha(){
    $('gachaStatus').textContent=state.daily.gachaUsed?'今天已抽過，明天再來！':'今天尚未抽取，可免費抽一次。';
    $('gachaButton').disabled=state.daily.gachaUsed;$('gachaButton').textContent=state.daily.gachaUsed?'今日已抽取':'免費抽一次'
  }

  const GRADE_SCOPES={
    1:'20以內加減、100以內加減、數字比大小',
    2:'二位數加減、九九乘法、基礎除法、時間換算',
    3:'三位數加減、乘除、分數初步',
    4:'四位數加減、多位數乘除、因數、小數',
    5:'分數運算、小數、平均數、體積',
    6:'比與比例、百分率、速率、圓周長與面積',
    7:'指數與科學記號、一元一次方程式、二元一次聯立方程式、比例式、因數與倍數',
    8:'一元二次方程式、平方根與畢氏定理、乘法公式與多項式、等差級數與等比數列、三角形內外角'
  };

  const GRADE_TYPES={
    1:['g1_add20','g1_sub20','g1_add100','g1_compare'],
    2:['g2_addsub','g2_mul','g2_div','g2_time'],
    3:['g3_addsub','g3_mul','g3_div','g3_fraction'],
    4:['g4_addsub','g4_mul','g4_div','g4_factor','g4_decimal'],
    5:['g5_fraction','g5_decimal','g5_average','g5_volume'],
    6:['g6_ratio','g6_percent','g6_speed','g6_circle'],
    7:['g7_exp','g7_sci','g7_linear','g7_system','g7_proportion','g7_factor'],
    8:['g8_quadratic','g8_sqrt','g8_pythagorean','g8_formula','g8_poly','g8_arithmetic','g8_geometric','g8_triangle']
  };

  function gcd(a,b){while(b){[a,b]=[b,a%b]}return Math.abs(a)}
  function lcm(a,b){return Math.abs(a*b)/gcd(a,b)}
  function availableTypes(){return GRADE_TYPES[state.grade]||GRADE_TYPES[1]}

  function chooseAdaptiveType(){
    const types=availableTypes(),weighted=[];
    types.forEach(type=>{
      const acc=typeAccuracy(type);
      let weight=3;
      if(acc!==null){weight=acc<.6?8:acc<.8?5:2}
      for(let i=0;i<weight;i++)weighted.push(type)
    });
    return weighted[rand(0,weighted.length-1)]
  }

  function generateQuestion(){
    const type=chooseAdaptiveType();
    let text='',answer=0;

    if(type==='g1_add20'){const a=rand(0,15),b=rand(0,20-a);text=`${a} + ${b} = ?`;answer=a+b}
    if(type==='g1_sub20'){const a=rand(5,20),b=rand(0,a);text=`${a} − ${b} = ?`;answer=a-b}
    if(type==='g1_add100'){
      let a=rand(10,70),b=rand(1,99-a);
      if(Math.random()<.5){text=`${a} + ${b} = ?`;answer=a+b}else{const c=a+b;text=`${c} − ${b} = ?`;answer=a}
    }
    if(type==='g1_compare'){const a=rand(1,99),b=rand(1,99);text=`${a} 和 ${b}，較大的數是多少？`;answer=Math.max(a,b)}

    if(type==='g2_addsub'){let a=rand(10,99),b=rand(10,99);if(Math.random()<.5){text=`${a} + ${b} = ?`;answer=a+b}else{if(b>a)[a,b]=[b,a];text=`${a} − ${b} = ?`;answer=a-b}}
    if(type==='g2_mul'){const a=rand(2,9),b=rand(2,9);text=`${a} × ${b} = ?`;answer=a*b}
    if(type==='g2_div'){const d=rand(2,9),q=rand(2,9);text=`${d*q} ÷ ${d} = ?`;answer=q}
    if(type==='g2_time'){const h=rand(1,4);text=`${h} 小時等於多少分鐘？`;answer=h*60}

    if(type==='g3_addsub'){let a=rand(100,999),b=rand(100,999);if(Math.random()<.5){text=`${a} + ${b} = ?`;answer=a+b}else{if(b>a)[a,b]=[b,a];text=`${a} − ${b} = ?`;answer=a-b}}
    if(type==='g3_mul'){const a=rand(100,999),b=rand(2,9);text=`${a} × ${b} = ?`;answer=a*b}
    if(type==='g3_div'){const d=rand(2,9),q=rand(20,110);text=`${d*q} ÷ ${d} = ?`;answer=q}
    if(type==='g3_fraction'){const den=rand(3,10),n1=rand(1,den-1),n2=rand(1,den-n1);text=`同分母分數：${n1}/${den} + ${n2}/${den}\n答案的分子是多少？`;answer=n1+n2}

    if(type==='g4_addsub'){let a=rand(1000,9999),b=rand(1000,9999);if(Math.random()<.5){text=`${a} + ${b} = ?`;answer=a+b}else{if(b>a)[a,b]=[b,a];text=`${a} − ${b} = ?`;answer=a-b}}
    if(type==='g4_mul'){const a=rand(100,999),b=rand(10,49);text=`${a} × ${b} = ?`;answer=a*b}
    if(type==='g4_div'){const d=rand(10,30),q=rand(10,99);text=`${d*q} ÷ ${d} = ?`;answer=q}
    if(type==='g4_factor'){const n=rand(12,60),factors=[];for(let i=1;i<=n;i++)if(n%i===0)factors.push(i);const pick=factors[rand(0,factors.length-1)];text=`${pick} 是 ${n} 的因數嗎？\n是請輸入1，不是請輸入0`;answer=1}
    if(type==='g4_decimal'){const a=rand(10,99)/10,b=rand(10,99)/10;text=`${a.toFixed(1)} + ${b.toFixed(1)} = ?\n答案乘以10是多少？`;answer=Math.round((a+b)*10)}

    if(type==='g5_fraction'){const d=rand(3,12),a=rand(1,d-1),b=rand(1,d-1);text=`${a}/${d} + ${b}/${d}\n未約分答案的分子是多少？`;answer=a+b}
    if(type==='g5_decimal'){const a=rand(100,999)/10,b=rand(10,99)/10;text=`${a.toFixed(1)} − ${b.toFixed(1)} = ?\n答案乘以10是多少？`;answer=Math.round((a-b)*10)}
    if(type==='g5_average'){const a=rand(40,90),b=rand(40,90),c=rand(40,90);const sum=a+b+c;const adjusted=sum-sum%3;text=`三次成績為 ${a}、${b}、${c+(3-sum%3)%3}\n平均是多少？`;answer=(adjusted+(3-sum%3)%3)/3}
    if(type==='g5_volume'){const a=rand(2,10),b=rand(2,10),c=rand(2,10);text=`長方體長${a}、寬${b}、高${c}\n體積是多少？`;answer=a*b*c}

    if(type==='g6_ratio'){const a=rand(2,9),b=rand(2,9),k=rand(2,8);text=`${a}：${b} = ${a*k}：□`;answer=b*k}
    if(type==='g6_percent'){const p=[10,20,25,50,75][rand(0,4)],whole=rand(2,20)*20;text=`${whole} 的 ${p}% 是多少？`;answer=whole*p/100}
    if(type==='g6_speed'){const speed=rand(30,90),time=rand(2,5);text=`每小時 ${speed} 公里，行駛 ${time} 小時\n路程是多少公里？`;answer=speed*time}
    if(type==='g6_circle'){const r=rand(2,10);if(Math.random()<.5){text=`圓的半徑為${r}，取圓周率3\n圓周長是多少？`;answer=2*3*r}else{text=`圓的半徑為${r}，取圓周率3\n圓面積是多少？`;answer=3*r*r}}

    if(type==='g7_exp'){const base=rand(2,6),m=rand(2,4),n=rand(1,3);text=`${base}^${m} × ${base}^${n} = ${base}^□\n指數是多少？`;answer=m+n}
    if(type==='g7_sci'){const a=rand(1,9),n=rand(2,6);text=`${a} × 10^${n} 展開後有幾個0？`;answer=n}
    if(type==='g7_linear'){const x=rand(-10,15),a=rand(2,8),b=rand(-20,20);text=`${a}x ${b>=0?'+':'−'} ${Math.abs(b)} = ${a*x+b}\nx = ?`;answer=x}
    if(type==='g7_system'){
      const x=rand(-8,12),y=rand(-8,12),a=rand(1,5),b=rand(1,5),c=rand(1,5),d=rand(1,5);
      text=`${a}x + ${b}y = ${a*x+b*y}\n${c}x + ${d}y = ${c*x+d*y}\n求 x + y`;answer=x+y
    }
    if(type==='g7_proportion'){const a=rand(2,9),b=rand(2,9),k=rand(2,10);text=`${a}/${b} = ${a*k}/x\nx = ?`;answer=b*k}
    if(type==='g7_factor'){const a=rand(12,60),b=rand(12,60);if(Math.random()<.5){text=`${a} 和 ${b} 的最大公因數是多少？`;answer=gcd(a,b)}else{text=`${a} 和 ${b} 的最小公倍數是多少？`;answer=lcm(a,b)}}

    if(type==='g8_quadratic'){
      let r1=rand(-8,8),r2=rand(-8,8);if(r1===r2)r2+=2;
      const sum=r1+r2,prod=r1*r2;
      text=`x² ${sum<=0?'+':'−'} ${Math.abs(sum)}x ${prod>=0?'+':'−'} ${Math.abs(prod)} = 0\n較大的根是多少？`;answer=Math.max(r1,r2)
    }
    if(type==='g8_sqrt'){const n=rand(2,18);text=`√${n*n} = ?`;answer=n}
    if(type==='g8_pythagorean'){
      const triples=[[3,4,5],[5,12,13],[6,8,10],[8,15,17],[7,24,25]];
      const [a,b,c]=triples[rand(0,triples.length-1)];text=`直角三角形兩股為 ${a}、${b}\n斜邊是多少？`;answer=c
    }
    if(type==='g8_formula'){const a=rand(2,20),b=rand(2,20);text=`(${a} + ${b})² = ?`;answer=(a+b)**2}
    if(type==='g8_poly'){const a=rand(-8,8),b=rand(-8,8),c=rand(-8,8),d=rand(-8,8);text=`(${a}x + ${b}) + (${c}x + ${d})\nx 的係數是多少？`;answer=a+c}
    if(type==='g8_arithmetic'){
      const first=rand(1,20),diff=rand(2,10),n=rand(5,15);
      if(Math.random()<.5){text=`等差數列首項${first}，公差${diff}\n第${n}項是多少？`;answer=first+(n-1)*diff}
      else{const last=first+(n-1)*diff;text=`等差數列首項${first}，第${n}項為${last}\n前${n}項和是多少？`;answer=n*(first+last)/2}
    }
    if(type==='g8_geometric'){const first=rand(1,6),ratio=rand(2,4),n=rand(3,6);text=`等比數列首項${first}，公比${ratio}\n第${n}項是多少？`;answer=first*ratio**(n-1)}
    if(type==='g8_triangle'){
      const a=rand(20,100),b=rand(20,140-a);const c=180-a-b;
      if(Math.random()<.5){text=`三角形兩內角為 ${a}°、${b}°\n第三個內角是多少度？`;answer=c}
      else{text=`三角形兩個不相鄰內角為 ${a}°、${b}°\n對應外角是多少度？`;answer=a+b}
    }

    state.currentType=type;state.answer=answer;state.questionStartedAt=Date.now();
    $('question').textContent=text;
    $('questionType').textContent=TYPE_LABELS[type];
    $('gradeScope').textContent=`${state.grade}年級範圍：${GRADE_SCOPES[state.grade]}`;
    $('answer').value='';$('answer').focus();renderAI()
  }

  function updateAbility(correct,time){
    let delta=correct?8:-10;
    if(correct&&time<8)delta+=4;
    if(correct&&time>25)delta-=2;
    if(!correct&&state.combo===0)delta-=2;
    state.ability=Math.max(80,Math.min(500,state.ability+delta))
  }

  function rewardForAnswer(){
    const level=getLevel();
    const base=level<=2?10:level<=4?15:level<=6?20:30;
    const comboMultiplier=state.combo>=20?2:state.combo>=10?1.5:state.combo>=5?1.2:1;
    let reward=Math.floor(base*comboMultiplier);
    const hunger=state.pets[state.pet].hunger;
    if(hunger<50)return 1;
    if(hunger<90)return Math.floor(reward/2);
    return reward
  }

  function submitAnswer(){
    const value=$('answer').value.trim();
    if(!value){$('feedback').textContent='請先輸入答案。';return}
    const time=Math.max(1,(Date.now()-state.questionStartedAt)/1000);
    const isCorrect=Number(value)===state.answer;
    const stats=ensureTypeStats(state.currentType);
    stats.total++;stats.time+=time;
    if(isCorrect)stats.correct++;

    state.recent.push({correct:isCorrect,time,type:state.currentType});
    if(state.recent.length>20)state.recent.shift();

    const oldLevel=getLevel();
    state.daily.answered++;
    if(isCorrect){
      state.combo++;state.correct++;state.pets[state.pet].correct++;
      state.daily.correct++;state.daily.maxCombo=Math.max(state.daily.maxCombo,state.combo);
      const reward=rewardForAnswer();state.coins+=reward;flyCoins(reward);
      updateAbility(true,time);
      $('feedback').textContent=`答對了！連擊 ${state.combo}，獲得 ${reward} 金幣。`;
      sound('correct');reactPet()
    }else{
      state.combo=0;updateAbility(false,time);
      const penalty=Math.min(5,state.coins);
      state.coins-=penalty;
      $('feedback').textContent=`答案不正確，倒扣 ${penalty} 金幣。AI會稍微調整下一題，連擊歸零。`;
      sound('wrong')
    }
    const newLevel=getLevel();
    if(newLevel>oldLevel){
      $('levelModalTitle').textContent=`恭喜升到 Lv.${newLevel}！`;
      $('levelModalText').textContent=getStageIndex(newLevel)>getStageIndex(oldLevel)?'萌寵進化了！':'萌寵變得更強了！';
      $('levelModal').classList.remove('hidden');sound('level')
    }
    saveState();render();
    setTimeout(generateQuestion,900)
  }

  function renderPets(){
    const wrap=$('petList');wrap.innerHTML='';
    Object.entries(PETS).forEach(([key,p])=>{
      const b=document.createElement('button');
      b.className='pet-button'+(key===state.pet?' active':'');
      b.innerHTML=`<img src="${p.image}" alt="${p.label}"><span><b>${p.label}</b><br><small>${state.pets[key].name}・Lv.${getLevel(key)}</small></span>`;
      b.addEventListener('click',()=>{state.pet=key;saveState();render()});
      wrap.appendChild(b)
    })
  }

  function renderEvolution(){
    const level=getLevel(),p=PETS[state.pet],current=getEffectiveStageIndex(state.pet);
    $('evolutionGrid').innerHTML='';
    p.stages.forEach((s,i)=>{
      const div=document.createElement('div');
      div.className='evolution-card '+(i===current?'active ':'')+(i>current?'locked':'');
      div.innerHTML=`<div style="font-size:30px">${i<=current?(s.deco||'🐾'):'❔'}</div><b>${i<=current?s.name:'尚未解鎖'}</b><div>Lv.${s.level}</div>`;
      $('evolutionGrid').appendChild(div)
    })
  }

  function renderShop(){
    $('shopList').innerHTML='';
    Object.entries(FOODS).forEach(([key,f])=>{
      const row=document.createElement('div');row.className='item-row';
      row.innerHTML=`<div class="food-icon">${f.emoji}</div><div><b>${f.name}</b><br><small>${f.price} 金幣</small></div>`;
      const b=document.createElement('button');b.className='secondary';b.textContent='購買';b.disabled=state.coins<f.price;
      b.addEventListener('click',()=>{if(state.coins<f.price)return;state.coins-=f.price;state.inventory[key]++;sound('buy');saveState();render()});
      row.appendChild(b);$('shopList').appendChild(row)
    })
  }

  function renderBag(){
    $('bagList').innerHTML='';
    Object.entries(FOODS).forEach(([key,f])=>{
      const fav=PETS[state.pet].favorite===key;
      const div=document.createElement('div');div.className='bag-item';
      div.innerHTML=`<div class="food-icon">${f.emoji}</div><b>${f.name}</b><p>庫存：${state.inventory[key]}</p>${fav?'<p>⭐ 最愛</p>':''}`;
      const b=document.createElement('button');b.className='primary';b.textContent='餵食';
      b.disabled=state.inventory[key]<=0||state.pets[state.pet].hunger>=100;
      b.addEventListener('click',()=>{
        if(state.inventory[key]<=0)return;
        state.inventory[key]--;
        const ps=state.pets[state.pet];
        ps.hunger=Math.min(100,ps.hunger+(fav?25:10));
        if(ps.hunger>0){ps.starved=false;ps.stagePenalty=0}
        state.daily.feeds++;
        sound('feed');reactPet();saveState();render()
      });
      div.appendChild(b);$('bagList').appendChild(div)
    })
  }

  function renderTypeStats(){
    $('typeStats').innerHTML='';
    const entries=Object.entries(state.typeStats);
    if(!entries.length){$('typeStats').innerHTML='<p>尚無作答資料。</p>';return}
    entries.sort((a,b)=>b[1].total-a[1].total).forEach(([type,s])=>{
      const acc=Math.round(s.correct/s.total*100);
      const avg=(s.time/s.total).toFixed(1);
      const div=document.createElement('div');div.className='type-card';
      div.innerHTML=`<b>${TYPE_LABELS[type]}</b><span>正確率 ${acc}%</span><br><span>平均 ${avg} 秒</span><br><span>共 ${s.total} 題</span>`;
      $('typeStats').appendChild(div)
    })
  }

  function renderAI(){
    const acc=recentAccuracy(),avg=averageTime(),sw=strongestAndWeakest();
    const label=state.ability<140?'基礎暖身':state.ability<220?'初級挑戰':state.ability<320?'中級訓練':'高級挑戰';
    $('difficultyLabel').textContent=`${state.grade}年級｜${label}（能力值 ${state.ability}）`;
    $('recentAccuracy').textContent=state.recent.length?`${Math.round(acc*100)}%`:'尚無資料';
    $('avgTime').textContent=state.recent.length?`${avg.toFixed(1)} 秒`:'尚無資料';
    $('strongestType').textContent=sw.strong;$('weakestType').textContent=sw.weak;
    let suggestion='完成幾題後，AI會開始調整難度。';
    if(state.recent.length>=5){
      if(acc>=.85&&avg<12)suggestion='你答得又快又準，AI正在提高題目難度。';
      else if(acc<.55)suggestion='最近有點困難，AI會降低難度並增加弱點練習。';
      else suggestion=`AI會多安排「${sw.weak}」，同時保留你擅長的題型。`
    }
    $('aiSuggestion').textContent=suggestion
  }

  function render(){
    applyHungerDecay();
    const level=getLevel(),p=PETS[state.pet],ps=state.pets[state.pet],stageIndex=getEffectiveStageIndex(state.pet),stage=p.stages[stageIndex];
    $('coins').textContent=state.coins;$('level').textContent=level;$('correct').textContent=ps.correct;
    $('combo').textContent=state.combo;$('ability').textContent=state.ability;
    $('petImage').src=p.image;$('petNameInput').value=ps.name;$('stageBadge').textContent=stage.title;
    $('petStage').className=`pet-stage stage-${stageIndex+1}`;$('stageDeco').textContent=stage.deco;
    const exp=getExpression(ps.hunger);$('expressionFace').textContent=exp.face;$('expressionText').textContent=exp.text;
    $('expression').className=`expression ${exp.cls}`;
    $('hungerText').textContent=`${ps.hunger} / 100`;$('hungerFill').style.width=`${ps.hunger}%`;
    const next=level>=8?72:LEVEL_THRESHOLDS[level],prev=LEVEL_THRESHOLDS[level-1]||0;
    $('progressText').textContent=level>=8?'已滿級':`${ps.correct} / ${next}`;
    $('progressFill').style.width=level>=8?'100%':`${Math.max(0,Math.min(100,(ps.correct-prev)/(next-prev)*100))}%`;
    $('soundToggle').textContent=state.soundOn?'🔊 音效開啟':'🔇 音效關閉';
    $('rewardPreview').textContent=`目前基礎獎勵：${getLevel()<=2?10:getLevel()<=4?15:getLevel()<=6?20:30} 金幣`;
    $('gradeSelect').value=String(state.grade);
    $('gradeScope').textContent=`${state.grade}年級範圍：${GRADE_SCOPES[state.grade]}`;
    renderPets();renderEvolution();renderShop();renderBag();renderTypeStats();renderAI();renderDailyTasks();renderTeacherSummary();renderGacha()
  }

  $('submitAnswer').addEventListener('click',submitAnswer);
  $('answer').addEventListener('keydown',e=>{if(e.key==='Enter')submitAnswer()});
  $('petImage').addEventListener('click',()=>interactPet('pet'));
  document.querySelectorAll('.pet-interact').forEach(button=>{
    button.addEventListener('click',()=>interactPet(button.dataset.action))
  });
  $('gradeSelect').addEventListener('change',()=>{
    state.grade=Number($('gradeSelect').value);
    state.combo=0;
    saveState();render();generateQuestion();showNotice(`已切換到 ${state.grade} 年級`)
  });
  $('saveName').addEventListener('click',()=>{
    const name=$('petNameInput').value.trim();
    if(name)state.pets[state.pet].name=name;
    saveState();render();showNotice('名字已儲存')
  });
  $('soundToggle').addEventListener('click',()=>{state.soundOn=!state.soundOn;saveState();render()});
  $('exportSave').addEventListener('click',()=>{
    window.SaveSystem.exportToFile(state);
    showNotice('存檔已匯出')
  });
  $('importSave').addEventListener('click',()=>$('importSaveFile').click());
  $('importSaveFile').addEventListener('change',async event=>{
    const file=event.target.files&&event.target.files[0];
    if(!file)return;
    try{
      const imported=await window.SaveSystem.importFromFile(file,defaultState,todayKey());
      if(confirm('匯入後會覆蓋目前進度，確定繼續嗎？')){
        state=imported;
        saveState();
        applyHungerDecay();
        render();
        generateQuestion();
        showNotice('存檔匯入成功')
      }
    }catch(error){
      alert('匯入失敗：'+error.message)
    }finally{
      event.target.value=''
    }
  });
  $('gachaButton').addEventListener('click',useGacha);
  $('resetToday').addEventListener('click',()=>{
    if(confirm('確定要重設今天的紀錄嗎？')){
      state.daily={date:todayKey(),answered:0,correct:0,feeds:0,maxCombo:0,gachaUsed:false};saveState();render();showNotice('今日紀錄已重設')
    }
  });
  $('closeModal').addEventListener('click',()=>$('levelModal').classList.add('hidden'));

  applyHungerDecay();
  render();generateQuestion();
  setInterval(()=>{if(applyHungerDecay())render()},60000)
})();